 static ScrollViewer Scroll(UIElement content)=>new(){Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Padding=new Thickness(0,0,6,0)};
 static Button ActionButton(string text,Action action){var b=UiTheme.Action(text,action);b.Margin=new Thickness(0,0,7,0);return b;}
 static void Field(Panel panel,string label,FrameworkElement input){var caption=UiTheme.Text(label,11,"Muted");caption.TextWrapping=TextWrapping.Wrap;caption.Margin=new Thickness(0,10,0,7);panel.Children.Add(caption);input.Margin=new Thickness(0,0,0,8);panel.Children.Add(input);System.Windows.Automation.AutomationProperties.SetName(input,label);}
 void SelectPage(int index){pageHost.Content=pages[index];pageTitle.Text=new[]{"收入与排班","每周计薪时段","额外工作与调休日","日历与外观"}[index];for(int i=0;i<nav.Count;i++){nav[i].Background=i==index?UiTheme.Brush("#21826B"):Brushes.Transparent;nav[i].FontWeight=i==index?FontWeights.SemiBold:FontWeights.Normal;}}
 void RefreshCalendarInfo(){calendarInfo.Text="已加载："+string.Join(" / ",calendar.Years.Order());calendarHelp.Children.Clear();int year=int.Parse(loadedMonth[..4],CultureInfo.InvariantCulture);if(!calendar.Years.Contains(year)){var warning=UiTheme.Text($"缺少 {year} 年官方日历，当前按每周规则估算。",11);warning.Foreground=UiTheme.Brush("#C26435");warning.TextWrapping=TextWrapping.Wrap;calendarHelp.Children.Add(warning);calendarHelp.Children.Add(UiTheme.CalendarLink(year,$"打开 holiday-cn 的 {year}.json 页面 ↗"));}else{calendarHelp.Children.Add(UiTheme.CalendarLink(year,$"查看 {year} 年数据来源 ↗"));}}
 void ImportCalendar(){try{var picker=new OpenFileDialog{Filter="年度日历 JSON|*.json"};if(picker.ShowDialog()!=true)return;var imported=new HolidayCalendar();imported.Import(picker.FileName);int year=imported.Years.Single();string folder=Path.Combine(dataFolder,"calendars");Directory.CreateDirectory(folder);string dest=Path.Combine(folder,year+".json");if(!Path.GetFullPath(picker.FileName).Equals(Path.GetFullPath(dest),StringComparison.OrdinalIgnoreCase)){if(File.Exists(dest))File.Copy(dest,dest+".bak",true);File.Copy(picker.FileName,dest,true);}calendar.Import(dest);RefreshCalendarInfo();error.Text="日历已更新，保存所选月份后应用。";}catch(Exception ex){error.Text=ex.Message;}}
 void Fill(){month.Text=loadedMonth;income.Text=plan.Income.ToString(CultureInfo.InvariantCulture);single.IsChecked=plan.Mode==WorkMode.SingleRest;alternating.IsChecked=plan.Mode==WorkMode.Alternating;anchor.SelectedDate=DateTime.ParseExact(plan.DoubleWeekAnchor,"yyyy-MM-dd",CultureInfo.InvariantCulture);for(int i=0;i<7;i++)days[i].Text=Slots.Format(plan.Week.GetValueOrDefault(i)??new());rows.Clear();foreach(var d in plan.Overrides.OrderBy(x=>x.Key))rows.Add(new(){Date=d.Key,Work=d.Value.Work,Times=d.Value.Intervals==null?"":Slots.Format(d.Value.Intervals)});theme.SelectedIndex=original.Theme=="Light"?1:original.Theme=="Dark"?2:0;auto.IsChecked=original.AutoStart;}
 void LoadMonth(){try{_ =DateTime.ParseExact(month.Text.Trim()+"-01","yyyy-MM-dd",CultureInfo.InvariantCulture);if(MessageBox.Show(Window.GetWindow(this),"切换月份会放弃当前未保存的修改，是否继续？","载入月份",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;loadedMonth=month.Text.Trim();plan=original.GetMonth(loadedMonth);Fill();RefreshCalendarInfo();error.Text="";}catch{error.Text="月份请输入 yyyy-MM，例如 2026-11。";}}
 void Commit(){try{
  grid.CommitEdit(DataGridEditingUnit.Cell,true);grid.CommitEdit(DataGridEditingUnit.Row,true);
  if(month.Text.Trim()!=loadedMonth)throw new ArgumentException("请先点击“载入月份”，以免把当前设置保存到错误月份。");
  if(!decimal.TryParse(income.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out var amount))throw new ArgumentException("请输入有效的月收入。");
  var next=plan.Copy();next.Income=amount;next.Confirmed=true;next.Mode=single.IsChecked==true?WorkMode.SingleRest:alternating.IsChecked==true?WorkMode.Alternating:WorkMode.DoubleRest;next.DoubleWeekAnchor=(anchor.SelectedDate??throw new ArgumentException("请选择大小周基准日。")).ToString("yyyy-MM-dd");
  for(int i=0;i<7;i++)next.Week[i]=Slots.Parse(days[i].Text);
  next.Overrides.Clear();foreach(var row in rows){string key=row.Date.Trim();if(!DateOnly.TryParseExact(key,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out var d)||d.ToString("yyyy-MM")!=loadedMonth)throw new ArgumentException("额外日期必须是所选月份内的 yyyy-MM-dd 日期。");if(!next.Overrides.TryAdd(key,new DateRule{Work=row.Work,Intervals=string.IsNullOrWhiteSpace(row.Times)?null:Slots.Parse(row.Times)}))throw new ArgumentException("额外日期不能重复："+key);}
  next.Validate();new PayrollEngine(calendar).FreezeCalendar(next);
  if(new PayrollEngine(calendar).At(next,DateTime.Now).TotalSeconds==0)throw new ArgumentException("本月没有计薪时段，请填写周一或对应工作日时段。");
  var candidate=JsonSerializer.Deserialize<SettingsBook>(JsonSerializer.Serialize(original))!;candidate.Theme=theme.SelectedIndex==1?"Light":theme.SelectedIndex==2?"Dark":"System";candidate.AutoStart=auto.IsChecked==true;candidate.SaveMonth(next);save(candidate);Close();
 }catch(Exception ex){error.Text=ex.Message;}}
